import sys

def parse_input():
    input = sys.stdin.read().splitlines()
    n, m, k = map(int, input[0].split())
    pictures = []
    index = 1
    for _ in range(k + 1):
        pictures.append(input[index + 1:index + 1 + n])
        index += n + 1
    return n, m, k, pictures

def can_recolor(picture, x, y):
    target_color = '1' if picture[x][y] == '0' else '0'
    return (picture[x-1][y] == target_color and
            picture[x+1][y] == target_color and
            picture[x][y-1] == target_color and
            picture[x][y+1] == target_color)

def apply_operation(picture, operation):
    if operation[0] == '1':
        x, y = map(int, operation[1:])
        picture[x-1] = picture[x-1][:y-1] + ('1' if picture[x-1][y-1] == '0' else '0') + picture[x-1][y:]
    elif operation[0] == '2':
        pass

def find_sequence(n, m, k, pictures):
    from collections import defaultdict
    graph = defaultdict(list)
    for i in range(k + 1):
        for j in range(k + 1):
            if i != j:
                picture_i = pictures[i]
                picture_j = pictures[j]
                changes = sum(1 for x in range(1, n-1) for y in range(1, m-1) if picture_i[x][y] != picture_j[x][y])
                if changes == 1:
                    x, y = next((x, y) for x in range(1, n-1) for y in range(m-1) if picture_i[x][y] != picture_j[x][x])
                    if can_recolor(picture_i, x, y):
                        graph[i].append(('1', x + 1, y + 1, j))
                elif changes == 0:
                    graph[i].append(('2', j + 1, j))

    visited = [False] * (k + 1)
    path = []
    def dfs(node):
        if visited[node]:
            return False
        visited[node] = True
        path.append(node)
        if len(path) == k + 1:
            return True
        for op in graph[node]:
            if not visited[op[-1] - 1] and dfs(op[-1] - 1):
                path.append(op)
                return True
        path.pop()
        return False

    for i in range(k + 1):
        if dfs(i):
            break

    initial_index = path[-1] + 1
    operations = []
    for op in reversed(path[:-1]):
        if isinstance(op, tuple):
            operations.append(f"{op[0]} {op[1]} {op[2]}" if op[0] == '1' else f"{op[0]} {op[1]}")

    return initial_index, operations

n, m, k, pictures = parse_input()
initial_index, operations = find_sequence(n, m, k, pictures)
print(initial_index)
print(len(operations))
for op in operations:
    print(op)
